INSERT INTO reviews (review_id, store_id, user_id, rating, comment, created_at, updated_at) VALUES ('r-s1-1', 's1', 'u-demo', 5, '汉堡现做又多汁，松露薯条很香，和朋友吃得很满足。', 1790827200, 1790827200);
INSERT INTO reviews (review_id, store_id, user_id, rating, comment, created_at, updated_at) VALUES ('r-s1-2', 's1', 'u-amy', 5, '午餐套餐很划算，店员也很友善，下次会再来。', 1790654400, 1790654400);
INSERT INTO reviews (review_id, store_id, user_id, rating, comment, created_at, updated_at) VALUES ('r-s1-3', 's1', 'u-ming', 4, '芝士牛肉汉堡好吃，午饭时间稍微等了一会。', 1790481600, 1790481600);
INSERT INTO reviews (review_id, store_id, user_id, rating, comment, created_at, updated_at) VALUES ('r-s1-4', 's1', 'u-joyce', 5, '环境舒服，饮品清爽，适合逛苏豪时休息。', 1790222400, 1790222400);
INSERT INTO reviews (review_id, store_id, user_id, rating, comment, created_at, updated_at) VALUES ('r-s1-5', 's1', 'u-ken', 4, '份量充足，薯条上桌很热，建议提前订位。', 1789876800, 1789876800);
INSERT INTO reviews (review_id, store_id, user_id, rating, comment, created_at, updated_at) VALUES ('r-s2-1', 's2', 'u-amy', 4, '逛街后过来很方便，烟熏培根的味道不错。', 1790827200, 1790827200);
INSERT INTO reviews (review_id, store_id, user_id, rating, comment, created_at, updated_at) VALUES ('r-s2-2', 's2', 'u-ming', 5, '汉堡面包柔软，牛肉口感很好，值得再来。', 1790654400, 1790654400);
INSERT INTO reviews (review_id, store_id, user_id, rating, comment, created_at, updated_at) VALUES ('r-s2-3', 's2', 'u-joyce', 4, '饮品和薯条都不错，晚餐时店内比较热闹。', 1790481600, 1790481600);
INSERT INTO reviews (review_id, store_id, user_id, rating, comment, created_at, updated_at) VALUES ('r-s2-4', 's2', 'u-ken', 4, '套餐很适合两个人，服务速度也可以。', 1790222400, 1790222400);
INSERT INTO reviews (review_id, store_id, user_id, rating, comment, created_at, updated_at) VALUES ('r-s2-5', 's2', 'u-wai', 5, '卡座舒服，朋友很喜欢这里的莓果冰茶。', 1789876800, 1789876800);
INSERT INTO reviews (review_id, store_id, user_id, rating, comment, created_at, updated_at) VALUES ('r-s3-1', 's3', 'u-demo', 5, '小笼包汤汁丰富，牛肉汤面也很暖胃。', 1790827200, 1790827200);
